Tool response:
Tool: lookup_customer_id
Description: Retrieve the internal ID of a customer given their first and last name.
Parameters:
    {
      "type": "object",
      "properties": {
        "first_name": {
          "type": "string",
          "description": "First name of the customer",
          "title": "First Name"
        },
        "last_name": {
          "type": "string",
          "description": "Last name of the customer",
          "title": "Last Name"
        }
      },
      "required": [
        "first_name",
        "last_name"
      ]
    }

Tool response:
Tool: lookup_vehicle_id
Description: Retrieve the internal ID of a vehicle given its VIN.
Parameters:
    {
      "type": "object",
      "properties": {
        "vin": {
          "type": "string",
          "description": "VIN of the vehicle",
          "title": "Vin"
        }
      },
      "required": [
        "vin"
      ]
    }

Tool response:
Tool: record_new_sale
Description: Record a new sale for a customer and vehicle with financing details.
Parameters:
    {
      "type": "object",
      "properties": {
        "customer_first_name": {
          "type": "string",
          "title": "Customer First Name",
          "description": "First name of the customer"
        },
        "customer_last_name": {
          "type": "string",
          "title": "Customer Last Name",
          "description": "Last name of the customer"
        },
        "vehicle_vin": {
          "type": "string",
          "title": "Vehicle Vin",
          "description": "VIN of the vehicle being sold"
        },
        "sale_price": {
          "type": "number",
          "title": "Sale Price",
          "description": "Sale price of the vehicle"
        },
        "salesperson_id": {
          "type": "integer",
          "title": "Salesperson Id",
          "description": "ID of the salesperson recording the sale"
        },
        "financing_lender": {
          "type": "string",
          "title": "Financing Lender",
          "description": "Name of the financing lender"
        },
        "financing_apr": {
          "type": "number",
          "title": "Financing Apr",
          "description": "Annual Percentage Rate of the loan"
        },
        "financing_term_months": {
          "type": "integer",
          "title": "Financing Term Months",
          "description": "Term of the loan in months"
        }
      },
      "required": [
        "customer_first_name",
        "customer_last_name",
        "vehicle_vin",
        "sale_price",
        "salesperson_id",
        "financing_lender",
        "financing_apr",
        "financing_term_months"
      ]
    }
